"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { Globe, Network, Zap, ChevronDown } from "lucide-react";
import { useState, useEffect } from "react";
import SearchBar from "../ui/SearchBar";
import Logo from "../brand/Logo";
import GitHubIcon from "../ui/GitHubIcon";
import HeaderMobile from "./HeaderMobile";

export default function Header() {
  const pathname = usePathname();
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const navItems = [
    { href: "/", label: "Home", icon: Globe },
    { href: "/country", label: "Countries", icon: Globe },
    { href: "/asn", label: "ASN Database", icon: Network },
  ];

  const toggleMenu = () => setIsMenuOpen(!isMenuOpen);
  const closeMenu = () => setIsMenuOpen(false);

  useEffect(() => {
    if (isMenuOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isMenuOpen]);

  return (
    <header
      className={`border-b border-[rgba(34,229,122,.12)] bg-[rgba(4,7,5,.94)] backdrop-blur-[18px] sticky top-0 z-50 shadow-[0_12px_45px_rgba(0,0,0,.24)] transition-all duration-500 ${
        isMenuOpen ? "h-screen overflow-hidden" : "h-auto"
      }`}
    >
      <div
        className={`hidden md:block border-b border-[rgba(34,229,122,.1)] bg-gradient-to-r from-[rgba(34,229,122,.035)] via-transparent to-[rgba(34,229,122,.025)] transition-all duration-500 ${
          isMenuOpen
            ? "opacity-0 max-h-0 overflow-hidden border-0"
            : "opacity-100 max-h-[36px]"
        }`}
      >
        <div className="container mx-auto px-4 sm:px-6 lg:px-8 max-w-7xl">
          <div className="grid grid-cols-1 md:grid-cols-3 items-center gap-4 min-h-[36px] text-[#71877b] font-mono text-[10.5px] font-semibold tracking-[.02em]">
            <div className="flex items-center gap-3 justify-center md:justify-start">
              <span className="flex items-center gap-2">
                <span className="w-[7px] h-[7px] rounded-full bg-[#22e57a] shadow-[0_0_12px_rgba(34,229,122,.85)] animate-pulse" />
                <strong className="text-[#dff9eb] font-extrabold tracking-[.06em] uppercase">
                  Live
                </strong>
              </span>
              <span className="hidden sm:inline border-l border-[rgba(34,229,122,.13)] pl-3">
                IP Database v1.0.0
              </span>
            </div>
            <div className="flex items-center justify-center gap-4 text-[#8ca095]">
              <span className="flex items-center gap-1.5">
                <Zap size={14} className="text-[#7fe9ab]" />
                <span>24/7</span>
              </span>
              <span className="hidden sm:inline">·</span>
              <span className="hidden sm:inline">2.1M+ Networks</span>
              <span className="hidden sm:inline">·</span>
              <span className="hidden md:inline">248 Countries</span>
            </div>
            <div className="flex items-center justify-center md:justify-end gap-2">
              <Link
                href="/docs"
                className="flex items-center gap-1.5 text-[#8ca095] hover:text-white transition-colors"
              >
                <span>Docs</span>
                <ChevronDown
                  size={12}
                  className="transition-transform hover:translate-x-1"
                />
              </Link>
            </div>
          </div>
        </div>
      </div>

      <div
        className={`container mx-auto px-4 sm:px-6 lg:px-8 max-w-7xl transition-all duration-500 ${
          isMenuOpen ? "h-full flex items-start pt-4" : ""
        }`}
      >
        <div
          className={`flex items-center justify-between gap-4 ${
            isMenuOpen ? "w-full" : "h-[73px]"
          }`}
        >
          <Link href="/" className="flex-shrink-0 flex items-center gap-3">
            <Logo size="md" />
            <span className="hidden lg:inline-block px-2 py-1 border border-[rgba(34,229,122,.16)] rounded-md bg-[rgba(34,229,122,.035)] text-[#658074] font-mono text-[8.5px] font-extrabold tracking-[.11em] uppercase">
              Beta
            </span>
          </Link>

          <nav className="hidden md:flex items-center justify-center">
            <ul className="flex items-center gap-1 p-1 border border-[rgba(34,229,122,.08)] rounded-xl bg-[rgba(0,0,0,.12)]">
              {navItems.map((item) => {
                const isActive =
                  pathname === item.href ||
                  pathname?.startsWith(item.href + "/");
                return (
                  <li key={item.href}>
                    <Link
                      href={item.href}
                      className={`relative flex items-center gap-2 px-3 py-2 rounded-lg transition-all duration-200 text-sm font-semibold ${
                        isActive
                          ? "bg-[rgba(34,229,122,.07)] text-white"
                          : "text-[#8fa398] hover:text-white hover:bg-[rgba(34,229,122,.07)]"
                      }`}
                    >
                      <item.icon size={16} />
                      <span>{item.label}</span>
                      {isActive && (
                        <span className="absolute inset-x-3 bottom-1 h-[1px] bg-[#22e57a] shadow-[0_0_8px_#22e57a]" />
                      )}
                    </Link>
                  </li>
                );
              })}
            </ul>
          </nav>

          <div className="flex items-center gap-2">
            <a
              href="https://github.com/inject3r/ip-address-database"
              target="_blank"
              rel="noopener noreferrer"
              className="hidden lg:flex items-center gap-2 text-[#8fa398] hover:text-white transition-colors px-3 py-2 rounded-lg hover:bg-[rgba(34,229,122,.07)] text-sm font-semibold"
              aria-label="GitHub Repository"
            >
              <GitHubIcon size={18} />
              <span>Star</span>
            </a>

            <Link
              href="/country"
              className={`hidden md:flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-[#22e57a] to-[#45f793] text-[#05100a] font-extrabold text-sm rounded-lg shadow-[0_9px_28px_rgba(34,229,122,.2)] hover:shadow-[0_9px_34px_rgba(34,229,122,.4)] transition-all duration-300 hover:-translate-y-0.5 group ${
                isMenuOpen ? "hidden" : ""
              }`}
            >
              <span>Get Started</span>
              <Zap
                size={16}
                className="transition-transform group-hover:translate-x-1"
              />
            </Link>

            <div
              className={`hidden lg:block w-auto ${
                isMenuOpen ? "hidden" : ""
              }`}
            >
              <SearchBar />
            </div>

            <button
              onClick={toggleMenu}
              className={`md:hidden relative w-11 h-11 flex flex-col items-center justify-center gap-1.5 rounded-xl border transition-all duration-300 ${
                isMenuOpen
                  ? "border-[rgba(34,229,122,.4)] bg-[rgba(34,229,122,.08)]"
                  : "border-[rgba(34,229,122,.12)] hover:border-[rgba(34,229,122,.3)] hover:bg-[rgba(34,229,122,.04)]"
              }`}
              aria-label="Toggle menu"
            >
              <span
                className={`block w-5 h-0.5 bg-[#22e57a] rounded-full transition-all duration-300 ${
                  isMenuOpen ? "rotate-45 translate-y-2" : ""
                }`}
              />
              <span
                className={`block w-5 h-0.5 bg-[#22e57a] rounded-full transition-all duration-300 ${
                  isMenuOpen ? "opacity-0 scale-0" : ""
                }`}
              />
              <span
                className={`block w-5 h-0.5 bg-[#22e57a] rounded-full transition-all duration-300 ${
                  isMenuOpen ? "-rotate-45 -translate-y-2" : ""
                }`}
              />
            </button>
          </div>
        </div>

        <HeaderMobile isOpen={isMenuOpen} onClose={closeMenu} />
      </div>
    </header>
  );
}
