"use client";

import { useState, useEffect, useRef, useMemo } from "react";
import { Search, X, Globe, Network, Command } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useRouter } from "next/navigation";
import { useCountries, useASNs } from "@/hooks/useData";

interface SearchResult {
  type: "country" | "asn";
  code: string;
  name: string;
  countryCode?: string;
  networkCount?: number;
  org?: string;
}

export default function SearchBar() {
  const [query, setQuery] = useState<string>("");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const router = useRouter();
  const searchRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const resultsRef = useRef<HTMLUListElement>(null);

  // Get real data from hooks
  const { countries, loading: countriesLoading } = useCountries();
  const { asns, loading: asnsLoading } = useASNs();

  // Build search data from real sources
  const searchData = useMemo(() => {
    const countryList = countries.map((c) => ({
      code: c.code,
      name: c.name,
      networkCount: c.network_count,
    }));

    const asnList = asns.map((a) => ({
      code: a.asn,
      name: a.name || `AS${a.asn}`,
      country: a.country_code,
      org: a.org,
    }));

    return { countries: countryList, asns: asnList };
  }, [countries, asns]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        searchRef.current &&
        !searchRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
        setSelectedIndex(-1);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Cmd+K or Ctrl+K
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        inputRef.current?.focus();
        setIsOpen(true);
      }

      // Escape
      if (e.key === "Escape") {
        setIsOpen(false);
        setSelectedIndex(-1);
        inputRef.current?.blur();
      }

      // Arrow navigation
      if (isOpen && results.length > 0) {
        if (e.key === "ArrowDown") {
          e.preventDefault();
          setSelectedIndex((prev) => (prev + 1) % results.length);
        } else if (e.key === "ArrowUp") {
          e.preventDefault();
          setSelectedIndex(
            (prev) => (prev - 1 + results.length) % results.length,
          );
        } else if (e.key === "Enter" && selectedIndex >= 0) {
          e.preventDefault();
          handleSelect(results[selectedIndex]);
        }
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, results, selectedIndex]);

  // Scroll selected item into view
  useEffect(() => {
    if (selectedIndex >= 0 && resultsRef.current) {
      const items = resultsRef.current.children;
      if (items[selectedIndex]) {
        items[selectedIndex].scrollIntoView({
          block: "nearest",
          behavior: "smooth",
        });
      }
    }
  }, [selectedIndex]);

  const handleSearch = async (value: string) => {
    setQuery(value || "");
    setIsLoading(true);
    setSelectedIndex(-1);

    if (!value || value.length < 2) {
      setResults([]);
      setIsOpen(false);
      setIsLoading(false);
      return;
    }

    const searchLower = value.toLowerCase();

    // Simulate async search
    await new Promise((resolve) => setTimeout(resolve, 100));

    // Search in countries
    const countryResults = searchData.countries
      .filter(
        (c) =>
          c.name.toLowerCase().includes(searchLower) ||
          c.code.toLowerCase().includes(searchLower),
      )
      .map((c) => ({
        type: "country" as const,
        code: c.code,
        name: c.name,
        networkCount: c.networkCount,
      }));

    // Search in ASNs
    const asnResults = searchData.asns
      .filter(
        (a) =>
          a.name.toLowerCase().includes(searchLower) ||
          a.code.includes(value) ||
          a.org?.toLowerCase().includes(searchLower),
      )
      .map((a) => ({
        type: "asn" as const,
        code: a.code,
        name: a.name,
        countryCode: a.country,
        org: a.org,
      }));

    // Combine and limit results
    const combined = [...countryResults, ...asnResults].slice(0, 10);
    setResults(combined);
    setIsOpen(combined.length > 0);
    setIsLoading(false);
  };

  const handleSelect = (result: SearchResult) => {
    setQuery("");
    setResults([]);
    setIsOpen(false);
    setSelectedIndex(-1);

    if (result.type === "country") {
      router.push(`/country/${result.code.toLowerCase()}`);
    } else {
      const country = result.countryCode?.toLowerCase() || "us";
      router.push(`/asn/${country}/${result.code}`);
    }
  };

  // Show loading state while data is being fetched
  if (countriesLoading || asnsLoading) {
    return (
      <div className="relative w-full">
        <div className="relative">
          <Search
            className="absolute left-3 top-1/2 -translate-y-1/2 text-[#6f8a7d]"
            size={16}
          />
          <input
            disabled
            placeholder="Loading data..."
            value=""
            className="w-full bg-[#070b09]/50 border border-[rgba(34,229,122,.12)] rounded-xl pl-9 pr-4 pt-2.5 pb-[5px] text-sm text-[#6f8a7d] cursor-wait font-mono"
          />
        </div>
      </div>
    );
  }

  return (
    <div ref={searchRef} className="relative w-full">
      <div className="relative">
        <Search
          className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#6f8a7d] transition-colors group-focus-within:text-[#22e57a]"
          size={16}
        />
        <input
          ref={inputRef}
          type="text"
          value={query || ""}
          onChange={(e) => handleSearch(e.target.value)}
          onFocus={() => {
            if (query && query.length >= 2) {
              setIsOpen(true);
            }
          }}
          placeholder="Search countries or ASN..."
          className="w-full bg-[#070b09]/50 border border-[rgba(34,229,122,.12)] rounded-xl pl-10 pr-24 pt-2.5 pb-[5px] text-sm text-[#c6d2ca] placeholder-[#6f8a7d] focus:outline-none focus:border-[rgba(34,229,122,.4)] focus:ring-1 focus:ring-[rgba(34,229,122,.2)] transition-all duration-200 font-mono"
        />
        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1.5">
          {isLoading && (
            <div className="w-4 h-4 border-2 border-[#6f8a7d] border-t-[#22e57a] rounded-full animate-spin" />
          )}
          {query && !isLoading && (
            <button
              onClick={() => {
                setQuery("");
                setResults([]);
                setIsOpen(false);
                setSelectedIndex(-1);
                inputRef.current?.focus();
              }}
              className="text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors p-1 rounded-md hover:bg-[rgba(34,229,122,.06)]"
            >
              <X size={14} />
            </button>
          )}
          {!query && (
            <kbd className="hidden sm:flex items-center leading-0 gap-1 text-[8px] text-[#6f8a7d] bg-[#0a100d] px-2 py-1 rounded-md border border-[rgba(34,229,122,.1)] font-mono">
              <Command size={10} />K
            </kbd>
          )}
        </div>
      </div>

      <AnimatePresence>
        {isOpen && results.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: -8, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -8, scale: 0.98 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="absolute top-full left-0 right-0 mt-2 bg-[#070b09] border border-[rgba(34,229,122,.15)] rounded-xl shadow-[0_28px_80px_rgba(0,0,0,.72),0_0_45px_rgba(34,229,122,.08)] overflow-hidden z-50 backdrop-blur-xl"
          >
            <ul ref={resultsRef} className="py-2 max-h-80 overflow-y-auto">
              {results.map((result, index) => (
                <motion.li
                  key={`${result.type}-${result.code}`}
                  initial={{ opacity: 0, x: -8 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.03 }}
                  onClick={() => handleSelect(result)}
                  onMouseEnter={() => setSelectedIndex(index)}
                  className={`flex items-center gap-3 px-4 py-2.5 cursor-pointer transition-colors group ${
                    selectedIndex === index
                      ? "bg-[rgba(34,229,122,.08)]"
                      : "hover:bg-[rgba(34,229,122,.05)]"
                  }`}
                >
                  <div
                    className={`flex-shrink-0 w-8 h-8 rounded-lg flex items-center justify-center ${
                      result.type === "country"
                        ? "bg-[rgba(34,229,122,.1)]"
                        : "bg-[rgba(92,138,255,.1)]"
                    }`}
                  >
                    {result.type === "country" ? (
                      <Globe size={15} className="text-[#22e57a]" />
                    ) : (
                      <Network size={15} className="text-[#5c8aff]" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span
                        className={`text-sm font-medium truncate ${
                          selectedIndex === index
                            ? "text-[#22e57a]"
                            : "text-[#c6d2ca]"
                        }`}
                      >
                        {result.name}
                      </span>
                      <span className="text-[10px] px-2 py-0.5 rounded-md bg-[#0a100d] text-[#6f8a7d] font-mono flex-shrink-0 border border-[rgba(34,229,122,.06)]">
                        {result.code}
                      </span>
                    </div>
                    <div className="flex items-center gap-2 text-[11px] text-[#6f8a7d]">
                      {result.type === "country" && result.networkCount && (
                        <span>
                          {result.networkCount.toLocaleString()} networks
                        </span>
                      )}
                      {result.type === "asn" && result.countryCode && (
                        <span className="flex items-center gap-1">
                          <Globe size={10} />
                          {result.countryCode}
                        </span>
                      )}
                      {result.type === "asn" && result.org && (
                        <span className="text-[#4f6459]">• {result.org}</span>
                      )}
                    </div>
                  </div>
                  <div className="flex-shrink-0">
                    <span
                      className={`text-[9px] px-2 py-0.5 rounded-full font-mono font-bold tracking-wide ${
                        result.type === "country"
                          ? "bg-[rgba(34,229,122,.12)] text-[#22e57a]"
                          : "bg-[rgba(92,138,255,.12)] text-[#5c8aff]"
                      }`}
                    >
                      {result.type.toUpperCase()}
                    </span>
                  </div>
                </motion.li>
              ))}
            </ul>
            {results.length > 0 && (
              <div className="px-4 py-2 border-t border-[rgba(34,229,122,.06)] bg-[rgba(0,0,0,.2)] flex items-center justify-between text-[10px] text-[#4f6459] font-mono">
                <span>{results.length} results</span>
                <span className="flex items-center gap-2">
                  <kbd className="px-1.5 py-0.5 rounded bg-[#0a100d] border border-[rgba(34,229,122,.06)]">
                    ↑↓
                  </kbd>
                  <span>to navigate</span>
                  <kbd className="px-1.5 py-0.5 rounded bg-[#0a100d] border border-[rgba(34,229,122,.06)]">
                    Enter
                  </kbd>
                  <span>to select</span>
                  <kbd className="px-1.5 py-0.5 rounded bg-[#0a100d] border border-[rgba(34,229,122,.06)]">
                    Esc
                  </kbd>
                  <span>to close</span>
                </span>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
