"use client";

import { motion } from "framer-motion";

interface LogoProps {
  className?: string;
  size?: "sm" | "md" | "lg";
  variant?: "default" | "minimal" | "compact";
}

export default function Logo({
  className = "",
  size = "md",
  variant = "default",
}: LogoProps) {
  const sizes = {
    sm: { width: 32, height: 32, text: "text-base", gap: "gap-2" },
    md: { width: 38, height: 38, text: "text-xl", gap: "gap-2.5" },
    lg: { width: 46, height: 46, text: "text-2xl", gap: "gap-3" },
  };

  const { width, height, text, gap } = sizes[size];

  const showText = variant !== "compact";
  const showBadge = variant === "default" && size !== "sm";

  return (
    <div className={`flex items-center ${gap} ${className}`}>
      <div
        className="relative flex-shrink-0"
      >
        <svg
          width={width}
          height={height}
          viewBox="0 0 48 48"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          {/* Glow behind */}
          <circle
            cx="24"
            cy="24"
            r="30"
            fill="rgba(34,229,122,0.08)"
            className="blur-xl"
          />

          {/* Main background */}
          <rect
            x="2"
            y="2"
            width="44"
            height="44"
            rx="12"
            fill="#080d0b"
            stroke="rgba(34,229,122,0.25)"
            strokeWidth="1.5"
          />

          {/* Inner border glow */}
          <rect
            x="6"
            y="6"
            width="36"
            height="36"
            rx="8"
            fill="none"
            stroke="rgba(34,229,122,0.08)"
            strokeWidth="1"
          />

          {/* IP Text - larger and bolder */}
          <text
            x="24"
            y="32"
            textAnchor="middle"
            fill="#22e57a"
            fontSize="22"
            fontWeight="800"
            fontFamily="Inter, system-ui, sans-serif"
            letterSpacing="-0.04"
            className="select-none"
          >
            IP
          </text>

          {/* Decorative dots */}
          <circle cx="12" cy="12" r="2.5" fill="#22e57a" opacity="0.2" />
          <circle cx="36" cy="36" r="2.5" fill="#22e57a" opacity="0.2" />

          {/* Small connection lines */}
          <line
            x1="9"
            y1="24"
            x2="13"
            y2="24"
            stroke="#22e57a"
            strokeWidth="1.2"
            opacity="0.15"
          />
          <line
            x1="35"
            y1="24"
            x2="39"
            y2="24"
            stroke="#22e57a"
            strokeWidth="1.2"
            opacity="0.15"
          />
        </svg>
      </div>

      {showText && (
        <div className="flex flex-col leading-none">
          <span className={`font-bold ${text} text-[#f2fff8] tracking-tight`}>
            IP Database
          </span>
          {showBadge && (
            <span className="text-[9px] font-mono font-bold text-[#22e57a] tracking-[0.12em] uppercase opacity-70">
              Network Intelligence
            </span>
          )}
        </div>
      )}
    </div>
  );
}
