"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { Globe, Network, X, ChevronRight } from "lucide-react";

interface HeaderMobileProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function HeaderMobile({ isOpen, onClose }: HeaderMobileProps) {
  const pathname = usePathname();

  const navItems = [
    { href: "/", label: "Home", icon: Globe },
    { href: "/country", label: "Countries", icon: Globe },
    { href: "/asn", label: "ASN Database", icon: Network },
  ];

  return (
    <>
      <div
        className={`fixed inset-0 bg-black/80 backdrop-blur-sm z-40 transition-all duration-300 ${
          isOpen
            ? "opacity-100 pointer-events-auto"
            : "opacity-0 pointer-events-none"
        }`}
        onClick={onClose}
      />

      <div
        className={`fixed top-0 right-0 h-full w-[300px] sm:w-[360px] bg-[#0a120e] border-l border-[rgba(34,229,122,.08)] z-50 shadow-2xl transition-all duration-300 ease-out ${
          isOpen ? "translate-x-0" : "translate-x-full"
        }`}
      >
        <div className="flex items-center justify-between p-5 border-b border-[rgba(34,229,122,.08)]">
          <span className="text-[#dff9eb] font-bold text-lg tracking-tight">
            Menu
          </span>
          <button
            onClick={onClose}
            className="p-2 rounded-lg hover:bg-[rgba(34,229,122,.08)] transition-colors"
            aria-label="Close menu"
          >
            <X size={22} className="text-[#22e57a]" />
          </button>
        </div>

        <nav className="p-4">
          <ul className="space-y-1">
            {navItems.map((item) => {
              const isActive =
                pathname === item.href || pathname?.startsWith(item.href + "/");

              return (
                <li key={item.href}>
                  <Link
                    href={item.href}
                    onClick={onClose}
                    className={`flex items-center justify-between px-4 py-3.5 rounded-xl transition-all duration-200 group ${
                      isActive
                        ? "bg-[rgba(34,229,122,.08)] text-white"
                        : "text-[#8fa398] hover:text-white hover:bg-[rgba(34,229,122,.04)]"
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <item.icon
                        size={20}
                        className={isActive ? "text-[#22e57a]" : ""}
                      />
                      <span className="font-medium">{item.label}</span>
                    </div>
                    <ChevronRight
                      size={16}
                      className={`transition-all duration-200 ${
                        isActive
                          ? "text-[#22e57a] translate-x-1"
                          : "opacity-0 group-hover:opacity-100 group-hover:translate-x-1"
                      }`}
                    />
                  </Link>
                </li>
              );
            })}
          </ul>
        </nav>

        <div className="mx-4 border-t border-[rgba(34,229,122,.06)]" />

        <div className="p-4 space-y-3">
          <Link
            href="/docs"
            onClick={onClose}
            className="flex items-center justify-between px-4 py-3 rounded-xl text-[#8fa398] hover:text-white hover:bg-[rgba(34,229,122,.04)] transition-all duration-200 group"
          >
            <span className="font-medium">Documentation</span>
            <ChevronRight
              size={16}
              className="opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all duration-200"
            />
          </Link>

          <Link
            href="https://github.com/inject3r/ip-address-database"
            target="_blank"
            rel="noopener noreferrer"
            onClick={onClose}
            className="flex items-center justify-between px-4 py-3 rounded-xl text-[#8fa398] hover:text-white hover:bg-[rgba(34,229,122,.04)] transition-all duration-200 group"
          >
            <span className="font-medium">GitHub</span>
            <ChevronRight
              size={16}
              className="opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all duration-200"
            />
          </Link>

          <Link
            href="/country"
            onClick={onClose}
            className="flex items-center justify-center gap-2 w-full px-4 py-3.5 mt-2 bg-gradient-to-r from-[#22e57a] to-[#45f793] text-[#05100a] font-extrabold rounded-xl shadow-[0_8px_24px_rgba(34,229,122,.2)] hover:shadow-[0_8px_32px_rgba(34,229,122,.35)] transition-all duration-300 hover:-translate-y-0.5"
          >
            <span>Get Started</span>
            <ChevronRight size={18} />
          </Link>

          <div className="flex items-center justify-center gap-2 px-4 py-2 text-[#658074] font-mono text-[10px] font-semibold tracking-[.08em] uppercase">
            <span className="w-2 h-2 rounded-full bg-[#22e57a] shadow-[0_0_12px_rgba(34,229,122,.6)] animate-pulse" />
            <span>Live • v1.0.0</span>
          </div>
        </div>
      </div>
    </>
  );
}
